import re, glob, os, unicodedata, subprocess

def norm(s):
    s = unicodedata.normalize('NFKC', s)
    for a,b in [('\u201c','"'),('\u201d','"'),('\u2019',"'"),('\u2018',"'"),('\u2014','--'),('\u2013','-'),('\u00a0',' ')]:
        s=s.replace(a,b)
    s=re.sub(r'\*','',s)
    s=re.sub(r'\s+',' ',s)
    return s.strip()

files=[]
for pat in ['library/**/*','documents/**/*']:
    files += [f for f in glob.glob(pat, recursive=True) if os.path.isfile(f)]
corpus={}
for f in files:
    if f.endswith('.pdf'):
        txt=subprocess.run(['pdftotext',f,'-'],capture_output=True,text=True).stdout
    else:
        txt=open(f,encoding='utf-8',errors='replace').read()
    corpus[f]=norm(txt)
low={f:t.lower() for f,t in corpus.items()}

memo=open('deliverable/memo.md',encoding='utf-8').read()
# raw spans, no newline crossing, straight or curly quotes
pat = re.compile(r'[“"]([^“”"\n]{6,400})[”"]')
spans=[s.strip() for s in pat.findall(memo)]
uniq=sorted(set(spans), key=len, reverse=True)
matched=0; unmatched=[]
for s in uniq:
    t=norm(s).strip(' .,;:-')
    tl=t.lower()
    if len(t)<6: continue
    if any(tl in v for v in low.values()):
        matched+=1
    else:
        unmatched.append(s)
print('spans:',len(spans),'unique:',len(uniq),'matched:',matched,'unmatched:',len(unmatched))
print()
for u in unmatched:
    print('* ', u[:160])
