import json, os, re, glob, unicodedata, subprocess

def norm(s):
    s=unicodedata.normalize('NFKC',s)
    for a,b in [('\u201c','"'),('\u201d','"'),('\u2019',"'"),('\u2018',"'"),('\u2014','--'),('\u2013','-'),('\u00a0',' ')]:
        s=s.replace(a,b)
    return re.sub(r'\s+',' ',re.sub(r'\*','',s)).strip()

# ---- INDEX parse
idx=open('library/INDEX.md',encoding='utf-8').read()
index={}
for line in idx.splitlines():
    line=line.strip()
    if not line.startswith('|'): continue
    cells=[c.strip().strip('`').strip() for c in line.strip('|').split('|')]
    if len(cells)>=5 and cells[0].endswith('.md') and not set(cells[0])<=set('-: '):
        index[cells[0]]=cells[4]
print('INDEX entries parsed:', len(index))

d=json.load(open('deliverable/citations.json'))
prob=[]
for e in d:
    lf=e['library_file'].replace('library/','')
    if lf not in index: prob.append(('not in INDEX', e['cite'], lf))
    elif norm(e['status_checked']) != norm(index[lf]): prob.append(('status mismatch', e['cite'], repr(e['status_checked']), 'INDEX says', repr(index[lf])))
    if not os.path.isfile('library/'+lf): prob.append(('file missing', lf))
    if set(e)!={'cite','library_file','proposition','status_checked'}: prob.append(('keys', e['cite'], list(e)))
print('CITATION PROBLEMS:', prob if prob else 'none')
print('citable non-memo-bank INDEX files:', len([k for k in index if 'memo_bank' not in k]))
print('citations cover:', len(set(e['library_file'].replace('library/','') for e in d)), 'files')

# ---- quote audit (memo + QUESTIONS + STATUS) vs library+documents
corpus={}
for f in [p for pat in ['library/**/*','documents/**/*'] for p in glob.glob(pat, recursive=True) if os.path.isfile(p)]:
    corpus[f]=norm(subprocess.run(['pdftotext',f,'-'],capture_output=True,text=True).stdout if f.endswith('.pdf') else open(f,encoding='utf-8',errors='replace').read())
low=[v.lower() for v in corpus.values()]
pat=re.compile(r'[“"]([^“”"\n]{6,400})[”"]')
for doc in ['deliverable/memo.md','deliverable/QUESTIONS.md','deliverable/STATUS.md']:
    txt=open(doc,encoding='utf-8').read()
    spans=sorted(set(s.strip() for s in pat.findall(txt)), key=len, reverse=True)
    unmatched=[]
    for s in spans:
        frags=[norm(x).strip(' .,;:-') for x in re.split(r'…|\.\.\.', s) if len(norm(x).strip(' .,;:-'))>=6]
        if not frags: continue
        if all(any(f.lower() in v for v in low) for f in frags): continue
        unmatched.append(s)
    print(f'\n{doc}: {len(spans)} quoted spans; {len(unmatched)} not matched in library/documents:')
    for u in unmatched: print('   *', u[:130])
